import{_ as a,a0 as n,w as s,s as d,ao as u,I as e,x as o,a1 as i,A as r}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const k=JSON.parse('{"title":"Ciao：云集成高级编排器 | LCTT x X-CMD","titleTemplate":false,"description":"Ciao：云集成高级编排器 | LCTT (201710) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"Ciao：云集成高级编排器 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"Ciao：云集成高级编排器 | LCTT (201710) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201710/2017 Cloud Integrated Advanced Orchestrator","title":"Ciao：云集成高级编排器","tag":"201710","desc":""},"relativePath":"201710/2017 Cloud Integrated Advanced Orchestrator.md","filePath":"[post].md"}'),p={name:"201710/2017 Cloud Integrated Advanced Orchestrator.md"};function C(g,t,m,f,T,x){const l=n("Link");return s(),d("div",null,[t[19]||(t[19]=u('<h1 id="ciao-云集成高级编排器" tabindex="-1">Ciao：云集成高级编排器 <a class="header-anchor" href="#ciao-云集成高级编排器" aria-label="Permalink to “Ciao：云集成高级编排器”">​</a></h1><p><ruby>云集成高级编排器<rt>Cloud Integrated Advanced Orchestrator</rt></ruby> （Ciao） 是一个新的负载调度程序，用来解决当前云操作系统项目的局限性。Ciao 提供了一个轻量级，完全基于 TLS 的最小配置。它是 工作量无关的、易于更新、具有优化速度的调度程序，目前已针对 OpenStack 进行了优化。</p><p>其设计决策和创新方法在对安全性、可扩展性、可用性和可部署性的要求下进行：</p><ul><li><strong>可扩展性：</strong> 初始设计目标是伸缩超过 5,000 个节点。因此，调度器架构用新的形式实现： <ul><li>在 ciao 中，决策制定是去中心化的。它基于拉取模型，允许计算节点从调度代理请求作业。调度程序总能知道启动器的容量，而不要求进行数据更新，并且将调度决策时间保持在最小。启动器异步向调度程序发送容量。</li><li>持久化状态跟踪与调度程序决策制定相分离，它让调度程序保持轻量级。这种分离增加了可靠性、可扩展性和性能。结果是调度程序让出了权限并且这不是瓶颈。</li></ul></li><li><strong>可用性：</strong> 虚拟机、容器和裸机集成到一个调度器中。所有的负载都被视为平等公民。为了更易于使用，网络通过一个组件间最小化的异步协议进行简化，只需要最少的配置。Ciao 还包括一个新的、简单的 UI。所有的这些功能都集成到一起来简化安装、配置、维护和操作。</li><li><strong>轻松部署：</strong> 升级应该是预期操作，而不是例外情况。这种新的去中心化状态的体系结构能够无缝升级。为了确保基础设施（例如 OpenStack）始终是最新的，它实现了持续集成/持续交付（CI/CD）模型。Ciao 的设计使得它可以立即杀死任何 Ciao 组件，更换它，并重新启动它，对可用性影响最小。</li><li><strong>安全性是必需的：</strong> 与调度程序的连接总是加密的：默认情况下 SSL 是打开的，而不是关闭的。加密是从端到端：所有外部连接都需要 HTTPS，组件之间的内部通信是基于 TLS 的。网络支持的一体化保障了租户分离。</li></ul><p>初步结果证明是显著的：在 65 秒内启动一万个 Docker 容器和五千个虚拟机。进一步优化还在进行。</p>',5)),e("ul",null,[e("li",null,[t[1]||(t[1]=o("文档：",-1)),i(l,{href:"https://clearlinux.org/documentation/ciao/ciao.html"},{default:r(()=>[...t[0]||(t[0]=[o("https://clearlinux.org/documentation/ciao/ciao.html",-1)])]),_:1})]),e("li",null,[t[3]||(t[3]=o("Github 链接： ",-1)),i(l,{href:"https://github.com/01org/ciao"},{default:r(()=>[...t[2]||(t[2]=[o("https://github.com/01org/ciao(link is external)",-1)])]),_:1})]),e("li",null,[t[5]||(t[5]=o("邮件列表链接： ",-1)),i(l,{href:"https://lists.clearlinux.org/mailman/listinfo/ciao-devel"},{default:r(()=>[...t[4]||(t[4]=[o("https://lists.clearlinux.org/mailman/listinfo/ciao-devel",-1)])]),_:1})])]),t[20]||(t[20]=e("hr",null,null,-1)),e("p",null,[t[7]||(t[7]=o("via: ",-1)),i(l,{href:"https://clearlinux.org/ciao"},{default:r(()=>[...t[6]||(t[6]=[o("https://clearlinux.org/ciao",-1)])]),_:1})]),e("p",null,[t[11]||(t[11]=o("作者：",-1)),i(l,{href:"https://clearlinux.org/ciao"},{default:r(()=>[...t[8]||(t[8]=[o("ciao",-1)])]),_:1}),t[12]||(t[12]=o(" 译者：",-1)),i(l,{href:"https://github.com/geekpi"},{default:r(()=>[...t[9]||(t[9]=[o("geekpi",-1)])]),_:1}),t[13]||(t[13]=o(" 校对：",-1)),i(l,{href:"https://github.com/wxy"},{default:r(()=>[...t[10]||(t[10]=[o("wxy",-1)])]),_:1})]),e("p",null,[t[16]||(t[16]=o("本文由 ",-1)),i(l,{href:"https://github.com/LCTT/TranslateProject"},{default:r(()=>[...t[14]||(t[14]=[o("LCTT",-1)])]),_:1}),t[17]||(t[17]=o(" 原创编译，",-1)),i(l,{href:"https://linux.cn/"},{default:r(()=>[...t[15]||(t[15]=[o("Linux中国",-1)])]),_:1}),t[18]||(t[18]=o(" 荣誉推出",-1))])])}const v=a(p,[["render",C]]);export{k as __pageData,v as default};
